#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Cartogra demo host: walks docs/runbooks/deployment.md §1–8 interactively.
# Run with bash (not sh): bash infra/k8s/demo-host-wizard.sh
# Values persist in ~/.config/cartogra-demo/demo.env (0600); re-runs skip finished stages.
# BRANCH: the ref images.yml/deploy.yml run on. docs/phase-4-plan until plan 021 step 8 merges it, then main.

REPO=$(cd "$(dirname "${BASH_SOURCE[0]}")" && git rev-parse --show-toplevel)
BRANCH=docs/phase-4-plan
GH_REPO=allanweber/cartogra
DOMAIN=cartogra.dev
CONF_DIR="$HOME/.config/cartogra-demo"
S3=https://fsn1.your-objectstorage.com
BUCKET=cartogra-demo-backups
IMAGES=(gateway registry topology ingestion frontend acme)
export KUBECONFIG="$HOME/.kube/cartogra-demo"

# run CMD... echoes a command, then runs it.
run() { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET" >&2; "$@"; }

# begin ID: on a re-run, offers to skip a stage already finished.
begin() {
  [[ "$(_existing "DONE_$1" || true)" == 1 ]] || return 0
  note "Finished on an earlier run."
  confirm "Run this stage again?"
}
finished() { write_env "DONE_$1" 1; }

# gen KEY CMD...: generates a value once; later runs reuse the saved one.
gen() {
  local key="$1"; shift
  local v; v=$(_existing "$key" || true)
  [[ -n "$v" ]] || v=$("$@")
  write_env "$key" "$v"
}

run_wizard() {

TOTAL_STAGES=19
mkdir -p "$CONF_DIR" && chmod 700 "$CONF_DIR"
ENV_FILE="$CONF_DIR/demo.env"
# shellcheck disable=SC1090
[[ -f "$ENV_FILE" ]] && { set -a; . "$ENV_FILE"; set +a; }
cd "$REPO"

banner "Cartogra demo host (plan 021 · 7b)"

# ──────────────────────────────────────────────────────────────────────────
stage "Tools and repo"
missing=()
for t in hcloud kubectl helm kubeseal gh aws git jq openssl dig curl node pnpm ssh; do
  command -v "$t" >/dev/null 2>&1 || missing+=("$t")
done
if (( ${#missing[@]} )); then
  warn "missing: ${missing[*]}"
  [[ " ${missing[*]} " == *" kubeseal "* ]] && note "kubeseal: https://github.com/bitnami-labs/sealed-secrets/releases (kubeseal-*-linux-amd64.tar.gz → /usr/local/bin)"
  exit 1
fi
gh auth status >/dev/null 2>&1 || { warn "gh is not logged in: run gh auth login"; exit 1; }
[[ "$(git branch --show-current)" == "$BRANCH" ]] || { warn "check out $BRANCH first"; exit 1; }
say "All tools present, gh logged in, on $BRANCH."
note "Values are saved in $ENV_FILE (mode 0600, outside the repo)."
note "Copy every secret into your password manager as you go."
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Hetzner Cloud: API token and SSH key"
if begin hcloud; then
  open_url "https://console.hetzner.cloud/projects"
  step "Open (or create) the project for the demo."
  step "Security → API tokens → Generate API token, permission Read & Write."
  step "hcloud asks for the token next; paste it there."
  hcloud context list -o noheader -o columns=name | grep -qx cartogra || run hcloud context create cartogra
  run hcloud context use cartogra
  ask SSH_PUBKEY "SSH public key file (Enter = ~/.ssh/id_ed25519.pub):"
  [[ -n "$SSH_PUBKEY" ]] || SSH_PUBKEY="$HOME/.ssh/id_ed25519.pub"
  SSH_PUBKEY="${SSH_PUBKEY/#\~/$HOME}"
  [[ -f "$SSH_PUBKEY" ]] || { warn "no such file: $SSH_PUBKEY"; exit 1; }
  write_env SSH_PUBKEY "$SSH_PUBKEY"
  hcloud ssh-key describe cartogra-demo >/dev/null 2>&1 \
    || run hcloud ssh-key create --name cartogra-demo --public-key-from-file "$SSH_PUBKEY"
  finished hcloud
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Hetzner Object Storage: backup bucket"
if begin s3; then
  open_url "https://console.hetzner.cloud/projects"
  step "Same project → Security → S3 credentials → Generate credentials."
  step "The secret key is shown once; copy both now."
  ask_secret S3_ACCESS_KEY "Access key:"
  ask_secret S3_SECRET_KEY "Secret key:"
  write_env S3_ACCESS_KEY "$S3_ACCESS_KEY"
  write_env S3_SECRET_KEY "$S3_SECRET_KEY"
  export AWS_ACCESS_KEY_ID="$S3_ACCESS_KEY" AWS_SECRET_ACCESS_KEY="$S3_SECRET_KEY" AWS_DEFAULT_REGION=fsn1
  if aws s3api head-bucket --bucket "$BUCKET" --endpoint-url "$S3" >/dev/null 2>&1; then
    say "Bucket $BUCKET already exists."
  else
    run aws s3 mb "s3://$BUCKET" --endpoint-url "$S3" \
      || { warn "Name taken? Change backup.s3.bucket in values-demo.yaml + deployment.md §10, then re-run."; exit 1; }
  fi
  run aws s3api put-bucket-lifecycle-configuration --bucket "$BUCKET" --endpoint-url "$S3" \
    --lifecycle-configuration '{"Rules":[{"ID":"expire","Status":"Enabled","Filter":{"Prefix":"postgres/"},"Expiration":{"Days":7}}]}'
  finished s3
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Resend: sending domain and API key"
if begin resend; then
  open_url "https://resend.com/domains"
  step "Add domain $DOMAIN, create the DNS records it lists at your DNS provider."
  step "Wait until the domain shows Verified (can take a while)."
  pause "Press Enter once it is Verified"
  open_url "https://resend.com/api-keys"
  step "Create API key → permission Sending access → domain $DOMAIN."
  ask_secret RESEND_API_KEY "Paste the key (re_...):"
  write_env RESEND_API_KEY "$RESEND_API_KEY"
  finished resend
fi

# ──────────────────────────────────────────────────────────────────────────
stage "GitHub mirror: public org with Acme's 21 repos"
if begin mirror; then
  open_url "https://github.com/organizations/new"
  step "Create a free, public organization for the fake Acme repos."
  ask ACME_GITHUB_ORG "Organization name:"
  write_env ACME_GITHUB_ORG "$ACME_GITHUB_ORG"
  if confirm "Push the 21 Acme repos to $ACME_GITHUB_ORG now?"; then
    run gh auth setup-git
    (cd seed/acme-fintech && run pnpm install && ACME_GITHUB_ORG="$ACME_GITHUB_ORG" run pnpm acme repos --provider github)
  fi
  say "Repos in the org: $(gh repo list "$ACME_GITHUB_ORG" --limit 100 --json name --jq length)  (expect 21)"
  finished mirror
fi

# ──────────────────────────────────────────────────────────────────────────
stage "GitHub mirror: read-only token for the demo"
if begin token; then
  open_url "https://github.com/settings/personal-access-tokens/new"
  step "Resource owner: $ACME_GITHUB_ORG"
  step "Repository access: Public repositories (read-only). No other permissions."
  step "Never a personal token: the demo tenant is publicly readable."
  ask_secret ACME_GITHUB_TOKEN "Paste the token (github_pat_...):"
  write_env ACME_GITHUB_TOKEN "$ACME_GITHUB_TOKEN"
  n=$(curl -sf -H "Authorization: Bearer $ACME_GITHUB_TOKEN" "https://api.github.com/orgs/$ACME_GITHUB_ORG/repos?per_page=100" | jq length) \
    && say "Token sees $n repos (expect 21)." || warn "Token check failed; verify it before continuing."
  finished token
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Firewall and VM (starts billing)"
if begin vm; then
  myip=$(curl -s https://api.ipify.org || true)
  note "Your current public IP looks like: ${myip:-unknown}"
  ask MY_IP "Your IP for SSH (port 22):"
  [[ -n "$MY_IP" ]] || MY_IP="$myip"
  write_env MY_IP "$MY_IP"
  if ! hcloud firewall describe cartogra-demo >/dev/null 2>&1; then
    run hcloud firewall create --name cartogra-demo
    run hcloud firewall add-rule cartogra-demo --direction in --protocol tcp --port 22   --source-ips "$MY_IP/32"
    for p in 80 443 6443; do
      run hcloud firewall add-rule cartogra-demo --direction in --protocol tcp --port $p --source-ips 0.0.0.0/0 --source-ips ::/0
    done
  else
    note "Firewall exists. If your IP changed, update the port 22 rule in the console."
  fi
  if ! hcloud server describe cartogra-demo >/dev/null 2>&1; then
    confirm "Create CAX21 server cartogra-demo (fsn1, else nbg1, else hel1; billed hourly)?" || exit 1
    note "CAX21 is often out of stock. Retrying every 5 min until one location has it."
    note "Enter = retry now · Ctrl-C = stop (re-run resumes here)."
    attempt=0
    until hcloud server describe cartogra-demo >/dev/null 2>&1; do
      attempt=$((attempt + 1))
      for loc in fsn1 nbg1 hel1; do
        if out=$(hcloud server create --name cartogra-demo --type cax21 --image ubuntu-24.04 --location "$loc" \
              --ssh-key cartogra-demo --firewall cartogra-demo 2>&1); then
          printf '  %s✓ created%s in %s on attempt %s\n' "$GREEN" "$RESET" "$loc" "$attempt"
          command -v notify-send >/dev/null 2>&1 && notify-send "Cartogra wizard" "CAX21 created in $loc" || true
          break 2
        fi
        if ! grep -qiE 'unavailable|resource_limit|no.*capacity|placement' <<<"$out"; then
          warn "hcloud failed for a reason other than stock:"; note "$out"; exit 1
        fi
      done
      note "$(date +%H:%M) attempt $attempt: no CAX21 in fsn1/nbg1/hel1"
      read -r -t 300 _ || true
    done
  fi
  write_env DEMO_IP "$(hcloud server ip cartogra-demo)"
  say "Server IP: $DEMO_IP"
  finished vm
fi
DEMO_IP=$(_existing DEMO_IP || true)

# ──────────────────────────────────────────────────────────────────────────
stage "DNS: $DOMAIN → $DEMO_IP"
step "At your DNS provider: A record for $DOMAIN → $DEMO_IP (remove any other A/AAAA for it)."
until [[ "$(dig +short "$DOMAIN" | tail -n1)" == "$DEMO_IP" ]]; do
  note "dig says: $(dig +short "$DOMAIN" | tr '\n' ' ')"
  pause "Not yet. Press Enter to check again"
done
say "$DOMAIN resolves to $DEMO_IP."

# ──────────────────────────────────────────────────────────────────────────
stage "k3s and admin kubeconfig"
if begin k3s; then
  if ! kubectl get nodes >/dev/null 2>&1; then
    run ssh -o StrictHostKeyChecking=accept-new "root@$DEMO_IP" \
      "curl -sfL https://get.k3s.io | INSTALL_K3S_EXEC='--tls-san $DEMO_IP --tls-san $DOMAIN' sh -"
    mkdir -p "$HOME/.kube"
    run scp "root@$DEMO_IP:/etc/rancher/k3s/k3s.yaml" "$KUBECONFIG"
    sed -i "s/127.0.0.1/$DEMO_IP/" "$KUBECONFIG" && chmod 600 "$KUBECONFIG"
  fi
  run kubectl get nodes
  note "Admin kubeconfig: $KUBECONFIG. It stays on this machine, never in CI."
  finished k3s
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Cluster add-ons: namespaces, cert-manager, Sealed Secrets, ClusterIssuer"
if begin addons; then
  run kubectl apply -f infra/k8s/cluster-setup.yaml
  run helm repo add jetstack https://charts.jetstack.io --force-update
  run helm repo add sealed-secrets https://bitnami.github.io/sealed-secrets --force-update
  run helm repo update
  run helm upgrade --install cert-manager jetstack/cert-manager --version v1.21.3 -n cert-manager --create-namespace \
    --set crds.enabled=true --wait --timeout 5m
  run helm upgrade --install sealed-secrets sealed-secrets/sealed-secrets --version 2.22.0 -n kube-system \
    --set fullnameOverride=sealed-secrets-controller --wait --timeout 5m
  ask LE_EMAIL "Email for Let's Encrypt expiry notices:"
  write_env LE_EMAIL "$LE_EMAIL"
  kubectl apply -f - <<YAML
apiVersion: cert-manager.io/v1
kind: ClusterIssuer
metadata:
  name: letsencrypt-prod
spec:
  acme:
    server: https://acme-v02.api.letsencrypt.org/directory
    email: $LE_EMAIL
    privateKeySecretRef:
      name: letsencrypt-prod
    solvers:
      - http01:
          ingress:
            ingressClassName: traefik
YAML
  finished addons
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Back up the Sealed Secrets key"
if begin sealkey; then
  keyfile="$CONF_DIR/sealed-secrets-key.yaml"
  (umask 077; kubectl -n kube-system get secret -l sealedsecrets.bitnami.com/sealed-secrets-key -o yaml > "$keyfile")
  say "Saved to $keyfile"
  warn "It decrypts every committed SealedSecret. Never commit it."
  step "Attach this file to your password manager entry now."
  pause "Press Enter once it is stored"
  confirm "Delete $keyfile from disk?" && rm -f "$keyfile"
  finished sealkey
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Secrets: generate, seal, apply"
if begin seal; then
  gen DB_PASSWORD openssl rand -hex 24
  gen JWT_SECRET openssl rand -base64 48
  gen ADMIN_PASSWORD openssl rand -hex 16
  gen CLUSTER_CREDENTIALS_KEY openssl rand -base64 32
  warn "Store DB_PASSWORD, JWT_SECRET, ADMIN_PASSWORD, CLUSTER_CREDENTIALS_KEY in your password manager."
  note "CLUSTER_CREDENTIALS_KEY must never change while the database lives."
  note "They are in $ENV_FILE."
  pause "Press Enter once stored"
  mkdir -p infra/k8s/sealed
  seal() {
    local ns=$1 name=$2; shift 2
    kubectl -n "$ns" create secret generic "$name" --dry-run=client -o yaml "$@" \
      | kubeseal --format yaml > "infra/k8s/sealed/$name.yaml"
    printf '  %s✓ sealed%s %s/%s\n' "$GREEN" "$RESET" "$ns" "$name"
  }
  DB=(--from-literal=DB_USERNAME=cartogra --from-literal=DB_PASSWORD="$DB_PASSWORD")
  seal cartogra gateway-secrets "${DB[@]}" \
    --from-literal=JWT_SECRET="$JWT_SECRET" \
    --from-literal=RESEND_API_KEY="$RESEND_API_KEY" \
    --from-literal=GOOGLE_CLIENT_SECRET=unset \
    --from-literal=GITHUB_CLIENT_SECRET=unset \
    --from-literal=BOOTSTRAP_ADMIN_PASSWORD="$ADMIN_PASSWORD"
  seal cartogra registry-secrets "${DB[@]}"
  seal cartogra topology-secrets "${DB[@]}"
  seal cartogra postgres-secrets "${DB[@]}"
  seal cartogra ingestion-secrets "${DB[@]}" --from-literal=CLUSTER_CREDENTIALS_KEY="$CLUSTER_CREDENTIALS_KEY"
  seal cartogra backup-secrets --from-literal=S3_ACCESS_KEY="$S3_ACCESS_KEY" --from-literal=S3_SECRET_KEY="$S3_SECRET_KEY"
  seal acme-system acme-bootstrap --from-literal=ACME_PASSWORD="$ADMIN_PASSWORD" --from-literal=ACME_GITHUB_TOKEN="$ACME_GITHUB_TOKEN"
  run kubectl apply -f infra/k8s/sealed/
  run kubectl -n cartogra get secrets     # expect 6
  run kubectl -n acme-system get secrets  # expect acme-bootstrap
  finished seal
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Commit the sealed files on $BRANCH"
if begin commit; then
  run git status --short infra/k8s/sealed/
  if confirm "Commit infra/k8s/sealed/ on $BRANCH and push?"; then
    run git add infra/k8s/sealed/
    git diff --cached --quiet || run git commit -s -m "chore(infra): sealed secrets for the demo host (#129)" \
      -m "Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>"
    run git push origin "$BRANCH"
  fi
  finished commit
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Images: build the branch head, make packages public"
SHA=$(git rev-parse HEAD)
[[ "$(git rev-parse "origin/$BRANCH")" == "$SHA" ]] || { warn "HEAD is not pushed; push $BRANCH first."; exit 1; }
write_env DEPLOY_SHA "$SHA"
ok=$(gh run list --repo "$GH_REPO" --workflow images.yml --branch "$BRANCH" --status success --limit 20 \
  --json headSha --jq "map(select(.headSha==\"$SHA\")) | length")
if (( ok == 0 )); then
  run gh workflow run images.yml --repo "$GH_REPO" --ref "$BRANCH"
  note "Waiting for the run to register…"
  rid=""
  until [[ -n "$rid" ]]; do
    rid=$(gh run list --repo "$GH_REPO" --workflow images.yml --branch "$BRANCH" --limit 5 \
      --json databaseId,headSha --jq "map(select(.headSha==\"$SHA\"))[0].databaseId // empty")
    [[ -n "$rid" ]] || read -r -t 5 _ || true
  done
  run gh run watch --repo "$GH_REPO" "$rid" --exit-status
fi
say "Images for ${SHA:0:12} exist."
public() {
  local tok; tok=$(curl -s "https://ghcr.io/token?scope=repository:allanweber/cartogra-$1:pull" | jq -r '.token // empty')
  [[ -n "$tok" ]] && curl -sf -o /dev/null -H "Authorization: Bearer $tok" \
    -H "Accept: application/vnd.oci.image.index.v1+json" \
    "https://ghcr.io/v2/allanweber/cartogra-$1/manifests/$SHA"
}
while :; do
  private=()
  for i in "${IMAGES[@]}"; do public "$i" || private+=("$i"); done
  (( ${#private[@]} )) || break
  warn "Not pulled anonymously yet: ${private[*]}"
  for i in "${private[@]}"; do open_url "https://github.com/users/allanweber/packages/container/cartogra-$i/settings"; done
  step "On each page: Danger Zone → Change visibility → Public."
  pause "Press Enter to re-check"
done
say "All 6 packages are public."
pause

# ──────────────────────────────────────────────────────────────────────────
stage "CI access: deployer kubeconfig, demo environment"
if begin ci; then
  ask ALERT_EMAIL "Who receives alert emails:"
  write_env ALERT_EMAIL "$ALERT_EMAIL"
  ACME_GITHUB_ORG=$(_existing ACME_GITHUB_ORG)
  tmpd=$(mktemp -d); CI="$tmpd/config"
  token=$(kubectl -n ci-deploy get secret deployer-token -o jsonpath='{.data.token}' | base64 -d)
  kubectl -n ci-deploy get secret deployer-token -o jsonpath='{.data.ca\.crt}' | base64 -d > "$tmpd/ca.crt"
  kubectl --kubeconfig "$CI" config set-cluster demo --server="https://$DEMO_IP:6443" \
    --certificate-authority="$tmpd/ca.crt" --embed-certs=true >/dev/null
  kubectl --kubeconfig "$CI" config set-credentials deployer --token="$token" >/dev/null
  kubectl --kubeconfig "$CI" config set-context demo --cluster=demo --user=deployer --namespace=cartogra >/dev/null
  kubectl --kubeconfig "$CI" config use-context demo >/dev/null
  say "can-i list pods -n cartogra:        $(kubectl --kubeconfig "$CI" auth can-i list pods -n cartogra || true)   (expect yes)"
  say "can-i get secrets -n kube-system:   $(kubectl --kubeconfig "$CI" auth can-i get secrets -n kube-system || true)   (expect no)"
  pause
  gh api -X PUT "repos/$GH_REPO/environments/demo" --input - >/dev/null <<JSON
{"reviewers":[{"type":"User","id":$(gh api user --jq .id)}]}
JSON
  printf '  %s✓ set%s environment demo (you approve each deploy)\n' "$GREEN" "$RESET"
  gh secret set KUBECONFIG --repo "$GH_REPO" --env demo < "$CI" && WRITTEN_SECRET+=("demo/KUBECONFIG")
  gh variable set ACME_GITHUB_ORG --repo "$GH_REPO" --env demo --body "$ACME_GITHUB_ORG"
  gh variable set ALERT_EMAIL --repo "$GH_REPO" --env demo --body "$ALERT_EMAIL"
  rm -rf "$tmpd"
  say "Set demo secret KUBECONFIG, variables ACME_GITHUB_ORG and ALERT_EMAIL."
  finished ci
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Deploy ${SHA:0:12} from $BRANCH"
if begin deploy; then
  run gh workflow run deploy.yml --repo "$GH_REPO" --ref "$BRANCH" -f sha="$SHA"
  note "Waiting for the run to register…"
  rid=""
  until [[ -n "$rid" ]]; do
    rid=$(gh run list --repo "$GH_REPO" --workflow deploy.yml --branch "$BRANCH" --limit 1 \
      --json databaseId,status --jq '.[0] | select(.status!="completed") | .databaseId // empty')
    [[ -n "$rid" ]] || read -r -t 5 _ || true
  done
  open_url "https://github.com/$GH_REPO/actions/runs/$rid"
  step "Click Review deployments → demo → Approve and deploy."
  note "Takes up to ~35 min (cartogra 15m + acme bootstrap 20m)."
  run gh run watch --repo "$GH_REPO" "$rid" --exit-status \
    || { warn "Deploy failed. Logs: gh run view $rid --log-failed; kubectl -n cartogra get pods"; exit 1; }
  finished deploy
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Verify (deployment.md §8)"
run kubectl -n cartogra get pods
note "expect all Ready, alerting 2/2"
say "acme-fintech Running pods: $(kubectl -n acme-fintech get pods --no-headers | grep -c Running || true)  (expect 21)"
run kubectl -n acme-system get jobs
note "expect none: the bootstrap Job is deleted on success"
until [[ "$(kubectl -n cartogra get certificate cartogra-tls -o jsonpath='{.status.conditions[?(@.type=="Ready")].status}' 2>/dev/null)" == True ]]; do
  pause "Certificate not Ready yet. Press Enter to re-check"
done
say "Certificate cartogra-tls Ready."
run curl -s "https://$DOMAIN/api/auth/features" | jq .data
note "expect signupEnabled false, guestEnabled true"
say "NetworkPolicy check (expect: gateway 200, ingestion blocked):"
kubectl -n cartogra run np-check --rm -i --restart=Never --image=curlimages/curl:8.10.1 -- \
  sh -c 'curl -sm3 -o /dev/null -w "gateway %{http_code}\n" http://gateway:8080/actuator/health/live;
         curl -sm3 -o /dev/null -w "ingestion %{http_code}\n" http://ingestion:8085/ || echo "ingestion blocked"'
open_url "https://$DOMAIN/demo"
step "Lands on the dashboard; write buttons disabled."
step "Graph shows Acme with observed edges within about a minute."
pause "Press Enter if all of the above matches (Ctrl-C if not)"

# ──────────────────────────────────────────────────────────────────────────
stage "Alert email and backup"
if begin alertbackup; then
  kubectl -n cartogra port-forward deploy/alerting 9093 >/dev/null 2>&1 & pf=$!
  read -r -t 3 _ || true
  run curl -s -XPOST localhost:9093/api/v2/alerts -H 'Content-Type: application/json' \
    -d '[{"labels":{"alertname":"DeliveryTest"},"annotations":{"summary":"Alert email test"}}]'
  kill "$pf" 2>/dev/null || true
  step "Check $(_existing ALERT_EMAIL) inbox (and spam) within a minute."
  note "If nothing: kubectl -n cartogra logs deploy/alerting -c alertmanager"
  pause "Press Enter once the email arrived"
  kubectl -n cartogra delete job backup-manual --ignore-not-found >/dev/null
  run kubectl -n cartogra create job --from=cronjob/postgres-backup backup-manual
  run kubectl -n cartogra wait --for=condition=complete job/backup-manual --timeout=10m
  export AWS_ACCESS_KEY_ID="$(_existing S3_ACCESS_KEY)" AWS_SECRET_ACCESS_KEY="$(_existing S3_SECRET_KEY)" AWS_DEFAULT_REGION=fsn1
  run aws s3 ls "s3://$BUCKET/postgres/" --endpoint-url "$S3"
  run kubectl -n cartogra delete job backup-manual
  finished alertbackup
fi

# ──────────────────────────────────────────────────────────────────────────
stage "External uptime monitor"
if begin uptime; then
  open_url "https://dashboard.uptimerobot.com/monitors"
  step "New monitor → type Keyword."
  step "URL: https://$DOMAIN/api/auth/features · keyword: guestEnabled · alert when keyword NOT exists."
  step "Interval 5 minutes; alert contact: your email."
  note "Keyword, not status: with the gateway down /api can fall through to the frontend (HTML, 200)."
  pause "Press Enter once the monitor is green"
  finished uptime
fi

finish
say "Next: tell Claude what deviated from deployment.md (it was never run before),"
say "then step 8: open the PR from $BRANCH."
printf '\n'
}

run_wizard "$@"; exit
